import os
import signal
import threading
import time
from django.db import connection
from django.http import JsonResponse
from rest_framework.views import APIView
from rest_framework.permissions import IsAuthenticated

# Global state for graceful shutdown
_shutdown_requested = False
_current_tenant_id = threading.local()

def graceful_shutdown_handler(signum, frame):
    """Handle SIGTERM for graceful shutdown during deployments."""
    global _shutdown_requested
    _shutdown_requested = True
    # Attempt to close DB connections cleanly
    try:
        connection.close()
    except Exception:
        pass

signal.signal(signal.SIGTERM, graceful_shutdown_handler)
signal.signal(signal.SIGUSR1, graceful_shutdown_handler)


def set_tenant_context(tenant_id):
    """Set the tenant context for the current database session.
    This sets the PostgreSQL session variable used by RLS policies."""
    _current_tenant_id.value = tenant_id
    with connection.cursor() as cursor:
        cursor.execute("SET app.current_tenant_id = %s", [str(tenant_id)])


def get_tenant_from_request(request):
    """Extract tenant ID from JWT claims."""
    return getattr(request.user, 'tenant_id', None)


class DocumentListView(APIView):
    permission_classes = [IsAuthenticated]

    def get(self, request):
        tenant_id = get_tenant_from_request(request)
        if not tenant_id:
            return JsonResponse({'error': 'No tenant context'}, status=403)

        set_tenant_context(tenant_id)

        # Small window here: if SIGTERM fires between set_tenant_context
        # and the query, connection.close() in the signal handler resets
        # the session. The next query will re-open a connection WITHOUT
        # the tenant context set, bypassing RLS.

        if _shutdown_requested:
            return JsonResponse({'error': 'Service shutting down'}, status=503)

        with connection.cursor() as cursor:
            cursor.execute(
                "SELECT id, title, content, tenant_id FROM documents ORDER BY created_at DESC LIMIT 50"
            )
            columns = [col[0] for col in cursor.description]
            results = [dict(zip(columns, row)) for row in cursor.fetchall()]

        return JsonResponse({'documents': results})


class DocumentDetailView(APIView):
    permission_classes = [IsAuthenticated]

    def get(self, request, doc_id):
        tenant_id = get_tenant_from_request(request)
        if not tenant_id:
            return JsonResponse({'error': 'No tenant context'}, status=403)

        set_tenant_context(tenant_id)

        with connection.cursor() as cursor:
            cursor.execute(
                "SELECT id, title, content, tenant_id, created_at FROM documents WHERE id = %s",
                [doc_id]
            )
            row = cursor.fetchone()

        if not row:
            return JsonResponse({'error': 'Not found'}, status=404)

        columns = ['id', 'title', 'content', 'tenant_id', 'created_at']
        doc = dict(zip(columns, row))
        return JsonResponse({'document': doc})


class DocumentCreateView(APIView):
    permission_classes = [IsAuthenticated]

    def post(self, request):
        tenant_id = get_tenant_from_request(request)
        if not tenant_id:
            return JsonResponse({'error': 'No tenant context'}, status=403)

        set_tenant_context(tenant_id)

        title = request.data.get('title', '')
        content = request.data.get('content', '')

        # Intentionally not sanitizing - RLS should enforce tenant isolation
        with connection.cursor() as cursor:
            cursor.execute(
                "INSERT INTO documents (title, content, tenant_id) VALUES (%s, %s, %s) RETURNING id",
                [title, content, tenant_id]
            )
            new_id = cursor.fetchone()[0]

        return JsonResponse({'id': new_id, 'status': 'created'}, status=201)
